class Linter {
    constructor(rest) {
        this.rest = rest;
        this.currentRequest = null;
    }

    async executeLintRequest(wikitext) {
        if (this.currentRequest) {
            this.currentRequest.abort();
        }

        this.currentRequest = new AbortController();
        const signal = this.currentRequest.signal;

        try {
            const response = await this.rest.post('/v1/transform/wikitext/to/lint', {
                wikitext: wikitext
            }, { signal });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            return await response.json();
        } catch (error) {
            if (error.name === 'AbortError') {
                mw.log.warn('[CodeMirror] Lint request aborted.');
            } else {
                mw.log.warn('[CodeMirror] Lint request failed:', error);
            }
            return null;
        } finally {
            this.currentRequest = null;
        }
    }
}
