/**
 * Purges IP addresses from the afl_ip and afl_ip_hex columns if the row was created more than
 * a specified number of days ago.
 *
 * @param int $days Number of days after which IP addresses should be purged
 */
public function purgeOldIPs(int $days): void {
    $cutoffTime = time() - ($days * 24 * 60 * 60);
    $this->db->update(
        'your_table_name',
        [
            'afl_ip' => null,
            'afl_ip_hex' => null
        ],
        [
            'created_at < ?' => $cutoffTime
        ],
        __METHOD__
    );
}
