class PageTriage {
    constructor() {
        this.urlUtils = mw.config.get('wgUrlUtils');
    }

    async showIp(link) {
        // Perform permission checks here
        if (!this.hasPermission()) {
            throw new Error('Permission denied');
        }

        // Existing code
        const ip = await this.fetchIp(link);
        return ip;
    }

    async fetchIp(link) {
        // Fetch IP logic
        const response = await fetch(this.urlUtils.parse(link).href);
        const data = await response.json();
        return data.ip;
    }

    hasPermission() {
        // Permission check logic
        return mw.config.get('wgUserIsSysop');
    }
}

// Usage
